robot-arm.project.vaproject:
{
  "schemaVersion": 1,
  "name": "Pick-and-place arm",
  "description": "A sample of the Physical AI and robotics package: a six-axis arm drawn as a solid you can turn, its links and joints anchored to its parts, the motors and encoders at its joints, the learned policy and the controller that move it, and the software they run in; and its workcell, with a table and two bins, where physical space shows each where it is.",
  "packages": [
    "physical-ai",
    "robot-arm"
  ]
}

robot-arm.scenarios/pick-a-part.vascenario:
{
  "id": "pick-a-part",
  "name": "Pick a part",
  "description": "The arm picks a part from its tray: the camera sees it, the policy picks joint targets, the controller and the motors move the arm to it, the encoders read each joint back, and the gripper closes on it.",
  "view": "control-loop",
  "steps": [
    {
      "id": "see",
      "description": "The wrist camera sees the part on its tray, 30 times a second.",
      "relations": [
        "camera-sees-workpiece"
      ],
      "dataOut": {
        "frames": 30
      }
    },
    {
      "id": "decide",
      "description": "From the camera’s images, the policy picks the next joint targets, 10 times a second.",
      "relations": [
        "policy-commands-controller"
      ],
      "dataOut": {
        "joint1": 35,
        "joint2": 42,
        "joint3": 32
      }
    },
    {
      "id": "reach",
      "description": "The joint controller turns each joint’s error into a torque for its motor, 1,000 times a second.",
      "relations": [
        "controller-commands-motor-1",
        "controller-commands-motor-2",
        "controller-commands-motor-3"
      ],
      "dataIn": {
        "error": 35
      },
      "dataOut": {
        "torque": 42.5
      }
    },
    {
      "id": "move",
      "description": "Motors 1 to 3 turn the arm toward the part and lower it over the tray.",
      "relations": [
        "motor-1-drives-joint-1",
        "motor-2-drives-joint-2",
        "motor-3-drives-joint-3"
      ]
    },
    {
      "id": "read-back",
      "description": "The encoders read the joints’ new angles back to the controller, closing the loop.",
      "relations": [
        "encoder-1-senses-joint-1",
        "encoder-2-senses-joint-2",
        "encoder-3-senses-joint-3"
      ],
      "dataOut": {
        "angle": 34.8
      }
    },
    {
      "id": "orient",
      "description": "Motors 4 to 6 roll the forearm, bend the wrist and turn the gripper to face the part.",
      "relations": [
        "controller-commands-motor-4",
        "controller-commands-motor-5",
        "controller-commands-motor-6",
        "motor-4-drives-joint-4",
        "motor-5-drives-joint-5",
        "motor-6-drives-joint-6"
      ]
    },
    {
      "id": "grasp",
      "description": "Over the part, the policy closes the gripper on it.",
      "relations": [
        "policy-commands-gripper"
      ]
    }
  ]
}

robot-arm.tours/pick-a-part.vatour:
{
  "id": "pick-a-part",
  "name": "Pick a part",
  "description": "The arm in its workcell, and one pick from bin A, followed on the control loop and in physical space, where the joints move the arm from bin A to bin B.",
  "steps": [
    {
      "id": "the-workcell",
      "viewState": {
        "view": "workcell",
        "space": {
          "camera": {
            "target": {
              "x": 0,
              "y": 1,
              "z": 0
            },
            "azimuth": 35,
            "elevation": 25,
            "distance": 3.6
          },
          "names": true
        }
      },
      "caption": {
        "title": "The workcell",
        "text": "The arm is bolted to the back of its table, a bin in front of it on either side: it picks each part from bin A and places it in bin B. A camera hangs above the bins.\n\nBeside the canvas, physical space shows each of them where it is, in meters."
      },
      "marks": [
        "arm",
        "bin-a",
        "bin-b",
        "workcell-camera"
      ]
    },
    {
      "id": "the-wrist-camera",
      "viewState": {
        "view": "kinematic-chain",
        "select": [
          "wrist-camera"
        ],
        "space": {
          "root": "arm",
          "camera": {
            "target": {
              "x": 0,
              "y": 0.72,
              "z": 0.5
            },
            "azimuth": 60,
            "elevation": 20,
            "distance": 0.9
          }
        }
      },
      "caption": {
        "title": "The wrist camera",
        "text": "The wrist camera is mounted on link 6, the tool flange, just above the gripper. It is drawn as the solid’s camera, and link 6 carries it, so it goes wherever the joints take the flange and looks past the gripper at the part it is about to pick.",
        "pointTo": "wrist-camera"
      },
      "marks": [
        "wrist-camera",
        "camera-on-link-6",
        "link-6"
      ]
    },
    {
      "id": "one-pick",
      "viewState": {
        "view": "control-loop",
        "scenario": "pick-a-part",
        "step": "see",
        "space": {
          "camera": {
            "target": {
              "x": 0,
              "y": 1.1,
              "z": 0
            },
            "azimuth": 35,
            "elevation": 20,
            "distance": 2.2
          }
        }
      },
      "caption": {
        "title": "One pick, step by step",
        "text": "Follow one pick on the control loop and in physical space:\n\n1. the wrist camera sees the part in bin A;\n2. the policy picks joint targets, and the controller drives the motors;\n3. the motors turn the joints, and the encoders read them back;\n4. the gripper closes on the part."
      },
      "play": {
        "scenario": "pick-a-part"
      }
    },
    {
      "id": "reach-bin-a",
      "viewState": {
        "view": "workcell",
        "space": {
          "camera": {
            "target": {
              "x": 0,
              "y": 0.95,
              "z": 0
            },
            "azimuth": 35,
            "elevation": 25,
            "distance": 2.1
          },
          "joints": {
            "joint-1": -34,
            "joint-2": 28,
            "joint-3": 18,
            "joint-5": 36
          }
        }
      },
      "caption": {
        "title": "Reach over bin A",
        "text": "Joint 1 turns the arm toward bin A, about the vertical through its base. The shoulder, the elbow and the wrist bend in the arm’s plane until the gripper hangs over the part, pointing down.",
        "pointTo": "bin-a"
      },
      "marks": [
        "bin-a",
        "workpiece"
      ]
    },
    {
      "id": "grip",
      "viewState": {
        "view": "workcell",
        "space": {
          "camera": {
            "target": {
              "x": 0,
              "y": 0.95,
              "z": 0
            },
            "azimuth": 35,
            "elevation": 25,
            "distance": 2.1
          },
          "joints": {
            "joint-1": -34,
            "joint-2": 47,
            "joint-3": 11,
            "joint-5": 38
          }
        }
      },
      "caption": {
        "title": "Down to the part, and grip",
        "text": "The shoulder leans further and the elbow opens, so the gripper comes straight down around the part; then it closes on it.",
        "pointTo": "workpiece"
      },
      "marks": [
        "gripper",
        "workpiece"
      ]
    },
    {
      "id": "lift",
      "viewState": {
        "view": "workcell",
        "space": {
          "camera": {
            "target": {
              "x": 0,
              "y": 0.95,
              "z": 0
            },
            "azimuth": 35,
            "elevation": 25,
            "distance": 2.1
          },
          "joints": {
            "joint-1": -34,
            "joint-2": 28,
            "joint-3": 18,
            "joint-5": 36
          }
        }
      },
      "caption": {
        "title": "Lift",
        "text": "The shoulder and the elbow take the gripper back up over bin A, the part held in it, clear of the bin’s walls.",
        "pointTo": "gripper"
      },
      "marks": [
        "gripper"
      ]
    },
    {
      "id": "over-bin-b",
      "viewState": {
        "view": "workcell",
        "space": {
          "camera": {
            "target": {
              "x": 0,
              "y": 0.95,
              "z": 0
            },
            "azimuth": 35,
            "elevation": 25,
            "distance": 2.1
          },
          "joints": {
            "joint-1": 34,
            "joint-2": 28,
            "joint-3": 18,
            "joint-5": 36
          }
        }
      },
      "caption": {
        "title": "Over to bin B",
        "text": "Joint 1 turns the whole arm across, to the other side of the table, while the shoulder, the elbow and the wrist keep their bends: the gripper stays level over bin B.",
        "pointTo": "bin-b"
      },
      "marks": [
        "bin-b"
      ]
    },
    {
      "id": "place",
      "viewState": {
        "view": "workcell",
        "space": {
          "camera": {
            "target": {
              "x": 0,
              "y": 0.95,
              "z": 0
            },
            "azimuth": 35,
            "elevation": 25,
            "distance": 2.1
          },
          "joints": {
            "joint-1": 34,
            "joint-2": 47,
            "joint-3": 11,
            "joint-5": 38
          }
        }
      },
      "caption": {
        "title": "Place it in bin B",
        "text": "The gripper comes down into bin B and opens, leaving the part there.\n\nA tour only moves the joints; the part itself stays drawn in bin A, where the model poses it.",
        "pointTo": "bin-b"
      },
      "marks": [
        "gripper",
        "bin-b"
      ]
    },
    {
      "id": "back-to-rest",
      "viewState": {
        "view": "workcell",
        "space": {
          "camera": {
            "target": {
              "x": 0,
              "y": 0.95,
              "z": 0
            },
            "azimuth": 35,
            "elevation": 25,
            "distance": 2.1
          }
        }
      },
      "caption": {
        "title": "Back to rest",
        "text": "With no positions of its own, the step glides every joint back to the position it keeps, ready for the next part.",
        "pointTo": "arm"
      },
      "marks": [
        "arm"
      ]
    }
  ]
}

