  "description": "A sample of the healthcare package: an invented clinic bills an invented insurer for a patient’s knee MRI, from the visit through its authorization to payment or denial, with the audit that reviews the claim afterwards and the patient’s care plan. Every person and organization in it is invented.",
  "packages": [
    "healthcare"
  ]
}

clinic-claim.scenarios/a-claim.vascenario:
{
  "id": "a-claim",
  "name": "A claim, from visit to payment",
  "description": "Jordan’s knee MRI is authorized, done and billed; Harbor’s review then decides whether every line is paid, or the contrast agent, which no authorization covers, is denied.",
  "view": "claim-journey",
  "steps": [
    {
      "id": "visit",
      "description": "Dr. Ortiz sees Jordan Reyes about her left knee, and suspects a torn meniscus.",
      "relations": [
        "ortiz-treats-jordan",
        "visit-for-jordan"
      ]
    },
    {
      "id": "covered",
      "description": "Jordan’s plan, Harbor Silver, pays for an MRI only with an authorization first.",
      "relations": [
        "jordan-covered"
      ],
      "dataIn": {
        "memberId": "HMH-482113"
      }
    },
    {
      "id": "request",
      "description": "Dr. Ortiz orders an MRI of the knee and requests the authorization.",
      "relations": [
        "ortiz-requests-auth"
      ],
      "dataOut": {
        "service": "MRI, left knee"
      }
    },
    {
      "id": "send-request",
      "description": "The request goes to Harbor Mutual Health.",
      "relations": [
        "auth-to-harbor"
      ]
    },
    {
      "id": "authorize",
      "description": "Harbor approves one MRI of the knee, without contrast, until 30 April.",
      "relations": [
        "auth-for-mri"
      ],
      "dataOut": {
        "authorization": "PA-20417",
        "quantity": 1
      }
    },
    {
      "id": "scan",
      "description": "On 12 March Dr. Haddad does the MRI, and gives a contrast agent with it.",
      "relations": [
        "haddad-treats-jordan",
        "appointment-for-jordan"
      ]
    },
    {
      "id": "bill",
      "description": "The clinic bills the visit, the MRI and the contrast agent, each on a line of claim C-1001.",
      "relations": [
        "visit-line-bills",
        "mri-line-bills",
        "contrast-line-bills"
      ],
      "dataOut": {
        "claim": "C-1001",
        "total": 1250
      }
    },
    {
      "id": "submit",
      "description": "The claim goes to Harbor, which checks each line against the plan and the authorization.",
      "relations": [
        "claim-to-harbor"
      ],
      "dataIn": {
        "claim": "C-1001"
      }
    },
    {
      "id": "pay-in-full",
      "description": "Every line passes, and Harbor pays the claim in full.",
      "relations": [
        "harbor-pays-claim"
      ],
      "dataOut": {
        "paid": 1250
      }
    },
    {
      "id": "deny-contrast",
      "description": "No authorization covers the contrast agent, so Harbor denies its line.",
      "relations": [
        "harbor-denies-contrast"
      ],
      "dataOut": {
        "denied": 120,
        "reason": "no authorization covers it"
      }
    },
    {
      "id": "pay-the-rest",
      "description": "Harbor pays the visit and the MRI.",
      "relations": [
        "harbor-pays-claim"
      ],
      "dataOut": {
        "paid": 1130
      }
    }
  ],
  "blocks": [
    {
      "id": "review",
      "kind": "decision",
      "question": "Does every line pass Harbor’s review?",
      "alternatives": [
        {
          "id": "passes",
          "label": "Yes",
          "steps": [
            "pay-in-full"
          ]
        },
        {
          "id": "contrast-denied",
          "label": "No, the contrast is not authorized",
          "steps": [
            "deny-contrast",
            "pay-the-rest"
          ]
        }
      ]
    }
  ]
}

clinic-claim.tours/a-claim-and-its-audit.vatour:
{
  "id": "a-claim-and-its-audit",
  "name": "A claim and its audit",
  "description": "Who is who, the claim line by line, the claim played to payment and to denial, and the audit that finds what the review let pass.",
  "steps": [
    {
      "id": "who-is-who",
      "viewState": {
        "view": "claim-journey"
      },
      "caption": {
        "title": "Who is who",
        "text": "Jordan Reyes is a patient of Northside Family Clinic, where Dr. Ortiz is her family doctor. Her plan, Harbor Silver, is offered by Harbor Mutual Health.\n\nEvery person and organization here is invented.",
        "pointTo": "jordan"
      },
      "marks": [
        "jordan",
        "clinic",
        "dr-ortiz",
        "harbor",
        "silver-plan",
        "jordan-covered"
      ]
    },
    {
      "id": "line-by-line",
      "viewState": {
        "view": "claim-journey",
        "select": [
          "claim"
        ]
      },
      "caption": {
        "title": "A claim, line by line",
        "text": "Claim C-1001 bills each service on a line of its own: the visit, the MRI and the contrast agent given with it.",
        "pointTo": "claim"
      },
      "marks": [
        "claim",
        "line-visit",
        "line-mri",
        "line-contrast"
      ],
      "reveal": [
        {
          "marks": [
            "auth",
            "auth-for-mri"
          ],
          "text": "The authorization, though, covers the MRI alone."
        }
      ]
    },
    {
      "id": "to-payment",
      "viewState": {
        "view": "claim-journey",
        "scenario": "a-claim",
        "step": "visit"
      },
      "caption": {
        "title": "From the visit to payment",
        "text": "Follow the claim:\n\n1. the visit, and the plan that asks for an authorization;\n2. the authorization, requested and approved;\n3. the scan, and the claim that bills it;\n4. Harbor’s review, which this time passes every line."
      },
      "play": {
        "scenario": "a-claim"
      },
      "advance": "after-scenario"
    },
    {
      "id": "to-denial",
      "viewState": {
        "view": "claim-journey",
        "scenario": "a-claim",
        "step": "submit",
        "choices": {
          "review": "contrast-denied"
        }
      },
      "caption": {
        "title": "When the review catches it",
        "text": "Had the review compared each line with the authorization, it would have denied the contrast agent and paid the rest.",
        "pointTo": "harbor-denies-contrast"
      },
      "marks": [
        "harbor-denies-contrast"
      ],
      "play": {
        "scenario": "a-claim",
        "from": "submit",
        "choices": {
          "review": "contrast-denied"
        }
      }
    },
    {
      "id": "the-audit",
      "viewState": {
        "view": "claim-audit"
      },
      "caption": {
        "title": "The audit finds it later",
        "text": "Harbor’s imaging audit of the quarter reviews the claim it paid in full, and finds the contrast agent billed without an authorization: 120 to recover.",
        "pointTo": "contrast-finding"
      },
      "marks": [
        "imaging-audit",
        "contrast-finding",
        "finding-in-contrast-line",
        "line-contrast"
      ],
      "dimRest": true
    }
  ]
}

