{
  "id": "invoice-to-ledger",
  "name": "From invoice to ledger",
  "description": "An invoice is recorded and posted, the café pays it, and payment matching decides how the payment is recorded: against the invoice, or as an unapplied receipt.",
  "view": "invoice-to-ledger",
  "steps": [
    {
      "id": "issue",
      "description": "The workshop issues invoice INV-0107 to the café for four oak tables: 2,000, and 400 of VAT.",
      "relations": [
        "workshop-issues-invoice"
      ],
      "dataOut": {
        "amount": 2400,
        "dueDate": "2026-04-30",
        "invoice": "INV-0107"
      }
    },
    {
      "id": "record-invoice",
      "description": "Journal entry JE-0107 records the invoice. Its first line debits accounts receivable by 2,400: the café owes it.",
      "relations": [
        "je-0107-records-invoice",
        "je-0107-receivable-debits"
      ]
    },
    {
      "id": "credit-sales",
      "description": "Its other lines credit sales by 2,000 and VAT payable by 400, so its debits and its credits balance at 2,400.",
      "relations": [
        "je-0107-sales-credits",
        "je-0107-vat-credits"
      ],
      "dataOut": {
        "credits": 2400,
        "debits": 2400
      }
    },
    {
      "id": "post-invoice",
      "description": "JE-0107 posts to the general ledger.",
      "relations": [
        "je-0107-posts"
      ]
    },
    {
      "id": "pay",
      "description": "The café pays the invoice by bank transfer: payment PAY-0112 of 2,400 reaches the workshop’s bank account.",
      "relations": [
        "cafe-pays-invoice"
      ],
      "dataOut": {
        "amount": 2400,
        "payment": "PAY-0112"
      }
    },
    {
      "id": "match",
      "description": "Payment matching reads the payment’s reference and looks for the open invoice it names.",
      "relations": [
        "matching-checks-payment"
      ],
      "dataIn": {
        "payment": "PAY-0112"
      }
    },
    {
      "id": "settle",
      "description": "The reference names INV-0107: the payment settles the invoice, which is now paid.",
      "relations": [
        "payment-settles-invoice"
      ],
      "dataOut": {
        "status": "paid"
      }
    },
    {
      "id": "record-payment",
      "description": "Journal entry JE-0112 records the payment. Its first line debits the bank account by 2,400.",
      "relations": [
        "je-0112-records-payment",
        "je-0112-bank-debits"
      ]
    },
    {
      "id": "clear-receivable",
      "description": "Its second line credits accounts receivable by 2,400: the café owes nothing more.",
      "relations": [
        "je-0112-receivable-credits"
      ],
      "dataOut": {
        "owed": 0
      }
    },
    {
      "id": "post-payment",
      "description": "JE-0112 posts to the general ledger.",
      "relations": [
        "je-0112-posts"
      ]
    },
    {
      "id": "record-unmatched",
      "description": "Journal entry JE-0113 records the payment all the same. Its first line debits the bank account by 2,400.",
      "relations": [
        "je-0113-records-payment",
        "je-0113-bank-debits"
      ]
    },
    {
      "id": "hold-unapplied",
      "description": "Its second line credits unapplied receipts by 2,400 until someone matches the payment by hand; the invoice stays open.",
      "relations": [
        "je-0113-unapplied-credits"
      ],
      "dataOut": {
        "status": "open"
      }
    },
    {
      "id": "post-unmatched",
      "description": "JE-0113 posts to the general ledger.",
      "relations": [
        "je-0113-posts"
      ]
    }
  ],
  "blocks": [
    {
      "id": "matches-invoice",
      "kind": "decision",
      "question": "Does the payment match an open invoice?",
      "alternatives": [
        {
          "id": "matched",
          "label": "Yes, INV-0107",
          "steps": [
            "settle",
            "record-payment",
            "clear-receivable",
            "post-payment"
          ]
        },
        {
          "id": "unmatched",
          "label": "No invoice matches",
          "steps": [
            "record-unmatched",
            "hold-unapplied",
            "post-unmatched"
          ]
        }
      ]
    }
  ]
}

workshop-books.tours/read-the-books.vatour:
{
  "id": "read-the-books",
  "name": "Read the books",
  "description": "The workshop’s general ledger, one invoice followed through its payment, and the reserve it keeps.",
  "steps": [
    {
      "id": "the-ledger",
      "viewState": {
        "view": "invoice-to-ledger"
      },
      "caption": {
        "title": "The general ledger",
        "text": "The workshop keeps its books by double entry. The general ledger holds its accounts, of five kinds:\n\n- assets and expenses, which a debit increases;\n- liabilities, equity and revenue, which a credit increases.\n\nEach journal entry draws its lines as rows: each line debits (Dr) or credits (Cr) one account, and an entry’s debits and credits always balance.",
        "pointTo": "general-ledger"
      },
      "marks": [
        "general-ledger",
        "je-0107"
      ]
    },
    {
      "id": "an-invoice-paid",
      "viewState": {
        "view": "invoice-to-ledger",
        "scenario": "invoice-to-ledger",
        "step": "issue"
      },
      "caption": {
        "title": "From invoice to ledger",
        "text": "Follow invoice INV-0107:\n\n1. the workshop issues it, and JE-0107 records it;\n2. the café pays it;\n3. payment matching finds the invoice the payment names;\n4. JE-0112 records the payment and clears what the café owed."
      },
      "play": {
        "scenario": "invoice-to-ledger"
      }
    },
    {
      "id": "when-nothing-matches",
      "viewState": {
        "view": "invoice-to-ledger",
        "scenario": "invoice-to-ledger",
        "step": "match",
        "choices": {
          "matches-invoice": "unmatched"
        }
      },
      "caption": {
        "title": "When no invoice matches",
        "text": "When the payment’s reference names no open invoice, the money is in the bank all the same: JE-0113 records it as an unapplied receipt, a liability, until someone matches it by hand. The invoice stays open."
      },
      "play": {
        "scenario": "invoice-to-ledger",
        "from": "match",
        "to": "post-unmatched",
        "choices": {
          "matches-invoice": "unmatched"
        }
      }
    },
    {
      "id": "the-reserve",
      "viewState": {
        "view": "reserve-portfolio"
      },
      "caption": {
        "title": "The reserve",
        "text": "The workshop keeps the money it does not need this year in a small portfolio. Each position holds one instrument, each instrument is exposed to a risk, and a control mitigates each risk.",
        "pointTo": "reserve-portfolio"
      },
      "marks": [
        "reserve-portfolio"
      ]
    }
  ]
}

